	private Optional<Vec3d> apoli$retryObstructedSpawnpointIfFailed(ServerWorld world, BlockPos pos, float angle, boolean forced, boolean alive, Operation<Optional<Vec3d>> original, ServerPlayerEntity mPlayer) {

