import java.util.Collections;
import java.util.LinkedList;
import java.util.Optional;
import java.util.stream.Collectors;

@Mixin(ServerPlayerEntity.class)
public abstract class ServerPlayerEntityMixin extends PlayerEntity implements ScreenHandlerListener, EndRespawningEntity {

    @Shadow
    private RegistryKey<World> spawnPointDimension;

    @Shadow
    private BlockPos spawnPointPosition;

    @Shadow
    @Final
    public MinecraftServer server;

    @Shadow
    public ServerPlayNetworkHandler networkHandler;

    public ServerPlayerEntityMixin(World world, BlockPos pos, float yaw, GameProfile gameProfile) {
        super(world, pos, yaw, gameProfile);
    }

    @Shadow
    public abstract void sendMessage(Text message, boolean actionBar);

    @Shadow
    public boolean notInAnyWorld;

    @Shadow private boolean spawnForced;

    @Shadow public abstract void setSpawnPoint(RegistryKey<World> dimension, @Nullable BlockPos pos, float angle, boolean forced, boolean sendMessage);

    @Shadow public abstract void sendMessage(Text message);

    @Shadow public abstract boolean shouldDamagePlayer(PlayerEntity player);

    @Inject(method = "trySleep", at = @At(value = "INVOKE",target = "Lnet/minecraft/server/network/ServerPlayerEntity;setSpawnPoint(Lnet/minecraft/registry/RegistryKey;Lnet/minecraft/util/math/BlockPos;FZZ)V"), cancellable = true)
    public void preventSleep(BlockPos pos, CallbackInfoReturnable<Either<SleepFailureReason, Unit>> info) {

        LinkedList<PreventSleepPower> preventSleepPowers = PowerHolderComponent.getPowers(this, PreventSleepPower.class)
            .stream()
            .filter(p -> p.doesPrevent(this.getWorld(), pos))
            .collect(Collectors.toCollection(LinkedList::new));

        if (preventSleepPowers.isEmpty()) {
            return;
        }

        preventSleepPowers.sort(Collections.reverseOrder(PreventSleepPower::compareTo));
        PreventSleepPower preventSleepPower = preventSleepPowers
            .getFirst();

        if (preventSleepPowers.stream().allMatch(PreventSleepPower::doesAllowSpawnPoint)) {
            this.setSpawnPoint(this.getWorld().getRegistryKey(), pos, this.getYaw(), false, true);
        }

        info.setReturnValue(Either.left(SleepFailureReason.OTHER_PROBLEM));
        this.sendMessage(preventSleepPower.getMessage(), true);

    }

    @Inject(at = @At("HEAD"), method = "getSpawnPointDimension", cancellable = true)
    private void modifySpawnPointDimension(CallbackInfoReturnable<RegistryKey<World>> info) {
        if (!this.apoli$isEndRespawning && (spawnPointPosition == null || hasObstructedSpawn()) && PowerHolderComponent.getPowers(this, ModifyPlayerSpawnPower.class).size() > 0) {
            ModifyPlayerSpawnPower power = PowerHolderComponent.getPowers(this, ModifyPlayerSpawnPower.class).get(0);
            info.setReturnValue(power.dimension);
        }
    }

    @Inject(at = @At("HEAD"), method = "getSpawnPointPosition", cancellable = true)
    private void modifyPlayerSpawnPosition(CallbackInfoReturnable<BlockPos> info) {
        if(!this.apoli$isEndRespawning && PowerHolderComponent.getPowers(this, ModifyPlayerSpawnPower.class).size() > 0) {
            if(spawnPointPosition == null) {
                info.setReturnValue(findPlayerSpawn());
            } else if(hasObstructedSpawn()) {
                networkHandler.sendPacket(new GameStateChangeS2CPacket(GameStateChangeS2CPacket.NO_RESPAWN_BLOCK, 0.0F));
                info.setReturnValue(findPlayerSpawn());
            }
        }
    }


    @Inject(at = @At("HEAD"), method = "isSpawnForced", cancellable = true)
    private void modifySpawnPointSet(CallbackInfoReturnable<Boolean> info) {
        if(!this.apoli$isEndRespawning && (spawnPointPosition == null || hasObstructedSpawn()) && PowerHolderComponent.hasPower(this, ModifyPlayerSpawnPower.class)) {
            info.setReturnValue(true);
        }
    }

    @Inject(method = "copyFrom", at = @At(value = "FIELD", opcode = Opcodes.GETFIELD, target = "Lnet/minecraft/server/network/ServerPlayerEntity;enchantmentTableSeed:I"))
    private void copyInventoryWhenKeeping(ServerPlayerEntity oldPlayer, boolean alive, CallbackInfo ci) {
        if(PowerHolderComponent.hasPower(oldPlayer, KeepInventoryPower.class)) {
            this.getInventory().clone(oldPlayer.getInventory());
        }
    }

    private boolean hasObstructedSpawn() {
        ServerWorld world = server.getWorld(spawnPointDimension);
        if(spawnPointPosition != null && world != null) {
            Optional optional = PlayerEntity.findRespawnPosition(world, spawnPointPosition, 0F, spawnForced, true);
            return !optional.isPresent();
        }
        return false;
    }

    private BlockPos findPlayerSpawn() {
        ModifyPlayerSpawnPower power = PowerHolderComponent.getPowers(this, ModifyPlayerSpawnPower.class).get(0);
        Pair<ServerWorld, BlockPos> spawn = power.getSpawn(true);
        if(spawn != null) {
            return spawn.getRight();
        }
        return null;
    }

    @Unique
    private ItemStack apoli$stackBeforeDrop;

    @Inject(method = "dropSelectedItem", at = @At("HEAD"))
    private void cacheItemStackBeforeDropping(boolean entireStack, CallbackInfoReturnable<Boolean> cir) {
        apoli$stackBeforeDrop = this.getInventory().getMainHandStack().copy();
    }

    @ModifyArg(method = "dropSelectedItem", at = @At(value = "INVOKE", target = "Lnet/minecraft/server/network/ServerPlayerEntity;dropItem(Lnet/minecraft/item/ItemStack;ZZ)Lnet/minecraft/entity/ItemEntity;"))
    private ItemStack checkItemUsageStopping(ItemStack itemStack) {
        if(this.isUsingItem() && !ItemStack.areItemsEqual(apoli$stackBeforeDrop, this.getInventory().getMainHandStack())) {
            StackReference reference = InventoryUtil.createStackReference(itemStack);
            ActionOnItemUsePower.executeActions(this, reference, apoli$stackBeforeDrop,
                    ActionOnItemUsePower.TriggerType.STOP, ActionOnItemUsePower.PriorityPhase.ALL);
            reference.get();
        }
        return itemStack;
    }

    @Unique
    private boolean apoli$isEndRespawning;

    @Override
    public void apoli$setEndRespawning(boolean endSpawn) {
        this.apoli$isEndRespawning = endSpawn;
    }

    @Override
    public boolean apoli$isEndRespawning() {
        return this.apoli$isEndRespawning;
    }

    @Override
    public boolean apoli$hasRealRespawnPoint() {
        return spawnPointPosition != null && !hasObstructedSpawn();
    }
}

package io.github.apace100.apoli.power;

import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.component.PowerHolderComponent;
import io.github.apace100.apoli.data.ApoliDataTypes;
import io.github.apace100.apoli.power.factory.PowerFactory;
import io.github.apace100.apoli.util.MiscUtil;
import io.github.apace100.calio.data.SerializableData;
import io.github.apace100.calio.data.SerializableDataTypes;
import net.minecraft.entity.Entity;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.util.Pair;
import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.function.Predicate;

public class EntitySetPower extends Power {

    private final Consumer<Pair<Entity, Entity>> actionOnAdd;
    private final Consumer<Pair<Entity, Entity>> actionOnRemove;
    private final int tickRate;

    private final Set<UUID> entityUuids = new HashSet<>();
    private final Map<UUID, Entity> entities = new HashMap<>();

    private final Set<UUID> tempUuids = new HashSet<>();
    private final Map<UUID, Long> tempEntities = new ConcurrentHashMap<>();

    private Integer startTicks = null;

    private boolean wasActive = false;
    private boolean removedTemps = false;

    public EntitySetPower(PowerType<?> type, LivingEntity entity, Consumer<Pair<Entity, Entity>> actionOnAdd, Consumer<Pair<Entity, Entity>> actionOnRemove, int tickRate) {
        super(type, entity);
        this.actionOnAdd = actionOnAdd;
        this.actionOnRemove = actionOnRemove;
        this.tickRate = tickRate;
        this.setTicking(true);
    }

    @Override
    public void onAdded() {
        removedTemps = entityUuids.removeIf(tempUuids::contains);
        tempUuids.clear();
    }

    @Override
    public void tick() {

        if (removedTemps) {

            this.removedTemps = false;
            PowerHolderComponent.syncPower(this.entity, this.type);

            return;

        }

        if (!tempEntities.isEmpty() && this.isActive()) {

            if (startTicks == null) {
                this.startTicks = entity.age % tickRate;
                return;
            }

            if (entity.age % tickRate == startTicks) {
                this.tickTempEntities();
            }

            this.wasActive = true;

        }

        else if (wasActive) {
            this.startTicks = null;
            this.wasActive = false;
        }

    }

    protected void tickTempEntities() {

        Iterator<Map.Entry<UUID, Long>> entryIterator = tempEntities.entrySet().iterator();
        long time = entity.getWorld().getTime();

        while (entryIterator.hasNext()) {

            Map.Entry<UUID, Long> entry = entryIterator.next();
            if (time < entry.getValue()) {
                continue;
            }

            UUID uuid = entry.getKey();
            Entity tempEntity = this.getEntity(uuid);

            entryIterator.remove();
            if (entityUuids.remove(uuid) | entities.remove(uuid) != null | tempUuids.remove(uuid)) {

                if (actionOnRemove != null) {
                    actionOnRemove.accept(new Pair<>(entity, tempEntity));
                }

                this.removedTemps = true;

            }

        }

    }

    public boolean validateEntities() {

        MinecraftServer server = entity.getServer();
        if (server == null) {
            return false;
        }

        Iterator<UUID> uuidIterator = entityUuids.iterator();
        boolean valid = true;

        while (uuidIterator.hasNext()) {

            UUID uuid = uuidIterator.next();
            if (MiscUtil.getEntityByUuid(uuid, server) != null) {
                continue;
            }

            uuidIterator.remove();
            entities.remove(uuid);
            tempUuids.remove(uuid);
            tempEntities.remove(uuid);

            valid = false;

        }

        return valid;

    }

    public boolean add(Entity entity) {
        return add(entity, null);
    }

    public boolean add(Entity entity, @Nullable Integer time) {

        if (entity == null || entity.isRemoved() || entity.getWorld().isClient) {
            return false;
        }

        UUID uuid = entity.getUuid();
        boolean addedToSet = false;

        if (time != null) {
            addedToSet |= tempUuids.add(uuid);
            tempEntities.compute(uuid, (prevUuid, prevTime) -> entity.getWorld().getTime() + time);
        }

        if (!entityUuids.contains(uuid)) {

            addedToSet |= entityUuids.add(uuid);
            entities.put(uuid, entity);

            if (actionOnAdd != null) {
                actionOnAdd.accept(new Pair<>(this.entity, entity));
            }

        }

        return addedToSet;

    }

    public boolean remove(@Nullable Entity entity) {
        return this.remove(entity, true);
    }

    public boolean remove(@Nullable Entity entity, boolean executeRemoveAction) {

        if (entity == null || entity.getWorld().isClient) {
            return false;
        }

        UUID uuid = entity.getUuid();
        boolean result = entityUuids.remove(uuid)
            | entities.remove(uuid) != null
            | tempUuids.remove(uuid)
            | tempEntities.remove(uuid) != null;

        if (executeRemoveAction && result && actionOnRemove != null) {
            actionOnRemove.accept(new Pair<>(this.entity, entity));
        }

        return result;

    }

    public boolean contains(Entity entity) {
        return entities.containsValue(entity) || entityUuids.contains(entity.getUuid());
    }

    public int size() {
        return entityUuids.size();
    }

    public void clear() {

        if (actionOnRemove != null) {

            for (UUID entityUuid : entityUuids) {
                actionOnRemove.accept(new Pair<>(this.entity, this.getEntity(entityUuid)));
            }

        }

        boolean wasNotEmpty = !entityUuids.isEmpty() || !tempUuids.isEmpty();

        tempUuids.clear();
        tempEntities.clear();
        entityUuids.clear();
        entities.clear();

        if (wasNotEmpty) {
            PowerHolderComponent.syncPower(this.entity, this.type);
        }

    }

    public Set<UUID> getIterationSet() {
        return new HashSet<>(entityUuids);
    }

    @Nullable
    public Entity getEntity(UUID uuid) {

        if (!entityUuids.contains(uuid)) {
            return null;
        }

        Entity entity = null;
        MinecraftServer server = this.entity.getServer();

        if (entities.containsKey(uuid)) {
            entity = entities.get(uuid);
        }

        if (server != null && (entity == null || entity.isRemoved())) {
            entity = MiscUtil.getEntityByUuid(uuid, server);
        }

        return entity;

    }

    @Override
    public NbtElement toTag() {

        NbtCompound rootNbt = new NbtCompound();

        NbtList entityUuidsNbt = new NbtList();
        NbtList tempUuidsNbt = new NbtList();

        for (UUID entityUuid : entityUuids) {
            NbtIntArray entityUuidNbt = NbtHelper.fromUuid(entityUuid);
            entityUuidsNbt.add(entityUuidNbt);
        }

        for (UUID tempUuid : tempUuids) {
            NbtIntArray tempUuidNbt = NbtHelper.fromUuid(tempUuid);
            tempUuidsNbt.add(tempUuidNbt);
        }

        rootNbt.put("Entities", entityUuidsNbt);
        rootNbt.put("TempEntities", tempUuidsNbt);
        rootNbt.putBoolean("RemovedTemps", removedTemps);

        return rootNbt;

    }

    @Override
    public void fromTag(NbtElement tag) {

        if (!(tag instanceof NbtCompound rootNbt)) {
            return;
        }

        tempUuids.clear();
        tempEntities.clear();
        entityUuids.clear();
        entities.clear();

        NbtList tempUuidsNbt = rootNbt.getList("TempEntities", NbtElement.INT_ARRAY_TYPE);
        for (NbtElement tempUuidNbt : tempUuidsNbt) {
            UUID tempUuid = NbtHelper.toUuid(tempUuidNbt);
            tempUuids.add(tempUuid);
        }

        NbtList entityUuidsNbt = rootNbt.getList("Entities", NbtElement.INT_ARRAY_TYPE);
        for (NbtElement entityUuidNbt : entityUuidsNbt) {
            UUID entityUuid = NbtHelper.toUuid(entityUuidNbt);
            entityUuids.add(entityUuid);
        }

        removedTemps = rootNbt.getBoolean("RemovedTemps");

    }

    public static void integrateLoadCallback(Entity loadedEntity, ServerWorld world) {
        PowerHolderComponent.syncPowers(loadedEntity, PowerHolderComponent.getPowers(loadedEntity, EntitySetPower.class, true)
            .stream()
            .filter(Predicate.not(EntitySetPower::validateEntities))
            .map(Power::getType)
            .toList());
    }

    public static void integrateUnloadCallback(Entity unloadedEntity, ServerWorld world) {

        Entity.RemovalReason removalReason = unloadedEntity.getRemovalReason();
        if (removalReason == null || !removalReason.shouldDestroy() || unloadedEntity instanceof PlayerEntity) {
            return;
        }

        for (ServerWorld otherWorld : world.getServer().getWorlds()) {

            for (Entity entity : otherWorld.iterateEntities()) {

                 PowerHolderComponent.syncPowers(entity, PowerHolderComponent.getPowers(entity, EntitySetPower.class, true)
                    .stream()
                    .filter(p -> p.remove(unloadedEntity, false))
                    .map(Power::getType)
                    .toList());

            }

        }

    }

    public static PowerFactory createFactory() {
        return new PowerFactory<>(
            Apoli.identifier("entity_set"),
            new SerializableData()
                .add("action_on_add", ApoliDataTypes.BIENTITY_ACTION, null)
                .add("action_on_remove", ApoliDataTypes.BIENTITY_ACTION, null)
                .add("tick_rate", SerializableDataTypes.POSITIVE_INT, 1),
            data -> (powerType, livingEntity) -> new EntitySetPower(
                powerType,
                livingEntity,
                data.get("action_on_add"),
                data.get("action_on_remove"),
                data.get("tick_rate")
            )
        ).allowCondition();
    }

}

package io.github.apace100.apoli.power;

import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.component.PowerHolderComponent;
import io.github.apace100.apoli.data.ApoliDataTypes;
import io.github.apace100.apoli.power.factory.PowerFactory;
import io.github.apace100.calio.data.SerializableData;
import io.github.apace100.calio.data.SerializableDataType;
import io.github.apace100.calio.data.SerializableDataTypes;
import net.minecraft.enchantment.EnchantmentHelper;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.inventory.Inventories;
import net.minecraft.inventory.Inventory;
import net.minecraft.inventory.StackReference;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.screen.*;
import net.minecraft.text.MutableText;
import net.minecraft.text.Text;
import net.minecraft.util.Pair;
import net.minecraft.util.collection.DefaultedList;
import net.minecraft.world.World;

import java.util.function.Predicate;

@SuppressWarnings("unused")
public class InventoryPower extends Power implements Active, Inventory {

    private final DefaultedList<ItemStack> container;
    private final MutableText containerTitle;
    private final ScreenHandlerFactory containerScreen;
    private final Predicate<Pair<World, ItemStack>> dropOnDeathFilter;

    private final boolean shouldDropOnDeath;
    private final boolean recoverable;

    private final int containerSize;

    private boolean dirty;

    public InventoryPower(PowerType<?> type, LivingEntity entity, String containerTitle, ContainerType containerType, boolean shouldDropOnDeath, Predicate<Pair<World, ItemStack>> dropOnDeathFilter, boolean recoverable) {
        super(type, entity);
        switch (containerType) {
            case DOUBLE_CHEST:
                containerSize = 54;
                this.containerScreen = (i, playerInventory, playerEntity) -> new GenericContainerScreenHandler(ScreenHandlerType.GENERIC_9X6, i,
                    playerInventory, this, 6);
                break;
            case CHEST:
                containerSize = 27;
                this.containerScreen = (i, playerInventory, playerEntity) -> new GenericContainerScreenHandler(ScreenHandlerType.GENERIC_9X3, i,
                    playerInventory, this, 3);
                break;
            case HOPPER:
                containerSize = 5;
                this.containerScreen = (i, playerInventory, playerEntity) -> new HopperScreenHandler(i, playerInventory, this);
                break;
            case DROPPER, DISPENSER:
            default:
                containerSize = 9;
                this.containerScreen = (i, playerInventory, playerEntity) -> new Generic3x3ContainerScreenHandler(i, playerInventory, this);
                break;
        }
        this.container = DefaultedList.ofSize(containerSize, ItemStack.EMPTY);
        this.containerTitle = Text.translatable(containerTitle);
        this.shouldDropOnDeath = shouldDropOnDeath;
        this.dropOnDeathFilter = dropOnDeathFilter;
        this.recoverable = recoverable;
        this.setTicking(true);
    }

    public enum ContainerType {
        CHEST,
        DOUBLE_CHEST,
        DROPPER,
        DISPENSER,
        HOPPER
    }

    @Override
    public void onLost() {
        if (recoverable) {
            dropItemsOnLost();
        }
    }

    @Override
    public void onUse() {

        if (this.isActive() && entity instanceof PlayerEntity player) {
            player.openHandledScreen(new SimpleNamedScreenHandlerFactory(containerScreen, containerTitle));
        }

    }

    @Override
    public void tick() {

        if (dirty) {
            PowerHolderComponent.syncPower(entity, type);
        }

        this.dirty = false;

    }

    @Override
    public NbtCompound toTag() {

        NbtCompound tag = new NbtCompound();
        Inventories.writeNbt(tag, container);

        return tag;

    }

    @Override
    public void fromTag(NbtElement tag) {

        if (!(tag instanceof NbtCompound rootNbt)) {
            return;
        }

        this.clear();
        Inventories.readNbt(rootNbt, container);

    }

    @Override
    public int size() {
        return containerSize;
    }

    @Override
    public boolean isEmpty() {
        return container.isEmpty();
    }

    @Override
    public ItemStack getStack(int slot) {
        return container.get(slot);
    }

    @Override
    public ItemStack removeStack(int slot, int amount) {

        ItemStack stack = Inventories.splitStack(container, slot, amount);
        if (!stack.isEmpty()) {
            this.markDirty();
        }

        return stack;

    }

    @Override
    public ItemStack removeStack(int slot) {

        ItemStack prevStack = this.getStack(slot);
        this.setStack(slot, ItemStack.EMPTY);

        return prevStack;

    }

    @Override
    public void setStack(int slot, ItemStack stack) {

        container.set(slot, stack);
        if (!stack.isEmpty()) {
            stack.setCount(Math.min(stack.getCount(), this.getMaxCountPerStack()));
        }

        this.markDirty();

    }

    @Override
    public void markDirty() {
        this.dirty = true;
    }

    @Override
    public boolean canPlayerUse(PlayerEntity player) {
        return player == this.entity;
    }

    @Override
    public void clear() {
        this.container.clear();
        this.markDirty();
    }

    @Deprecated(forRemoval = true)
    public StackReference getStackReference(int slot) {
        return new StackReference() {

            @Override
            public ItemStack get() {
                return InventoryPower.this.getStack(slot);
            }

            @Override
            public boolean set(ItemStack stack) {
                InventoryPower.this.setStack(slot, stack);
                return true;
            }

        };
    }

    public DefaultedList<ItemStack> getContainer() {
        return container;
    }

    public MutableText getContainerTitle() {
        return containerTitle;
    }

    public ScreenHandlerFactory getContainerScreen() {
        return containerScreen;
    }

    public boolean shouldDropOnDeath() {
        return shouldDropOnDeath;
    }

    public boolean shouldDropOnDeath(ItemStack stack) {
        return shouldDropOnDeath && dropOnDeathFilter.test(new Pair<>(entity.getWorld(), stack));
    }

    public void dropItemsOnDeath() {

        if (!(entity instanceof PlayerEntity playerEntity)) {
            return;
        }

        for (int i = 0; i < containerSize; ++i) {

            ItemStack currentStack = this.getStack(i).copy();
            if (!this.shouldDropOnDeath(currentStack)) {
                continue;
            }

            this.removeStack(i);
            if (!EnchantmentHelper.hasVanishingCurse(currentStack)) {
                playerEntity.dropItem(currentStack, true, false);
            }

        }

    }

    public void dropItemsOnLost() {

        if (!(entity instanceof PlayerEntity playerEntity)) {
            return;
        }

        for (int i = 0; i < containerSize; ++i) {
            playerEntity.getInventory().offerOrDrop(this.getStack(i));
        }

    }

    private Key key;

    @Override
    public Key getKey() {
        return key;
    }

    @Override
    public void setKey(Key key) {
        this.key = key;
    }

    public static PowerFactory createFactory() {
        return new PowerFactory<>(Apoli.identifier("inventory"),
            new SerializableData()
                .add("title", SerializableDataTypes.STRING, "container.inventory")
                .add("container_type", SerializableDataType.enumValue(ContainerType.class), ContainerType.DROPPER)
                .add("drop_on_death", SerializableDataTypes.BOOLEAN, false)
                .add("drop_on_death_filter", ApoliDataTypes.ITEM_CONDITION, null)
                .add("key", ApoliDataTypes.BACKWARDS_COMPATIBLE_KEY, new Active.Key())
                .add("recoverable", SerializableDataTypes.BOOLEAN, true),
            data ->
                (powerType, livingEntity) -> {
                    InventoryPower inventoryPower = new InventoryPower(
                        powerType,
                        livingEntity,
                        data.getString("title"),
                        data.get("container_type"),
                        data.getBoolean("drop_on_death"),
                        data.isPresent("drop_on_death_filter") ? data.get("drop_on_death_filter") : itemStack -> true,
                        data.getBoolean("recoverable")
                    );
                    inventoryPower.setKey(data.get("key"));
                    return inventoryPower;
                })
            .allowCondition();
    }
}

package io.github.apace100.apoli.power;

import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.data.ApoliDataTypes;
import io.github.apace100.apoli.power.factory.PowerFactory;
import io.github.apace100.calio.data.SerializableData;
import io.github.apace100.calio.data.SerializableDataTypes;
import net.minecraft.entity.LivingEntity;
import net.minecraft.inventory.Inventory;
import net.minecraft.item.ItemStack;
import net.minecraft.util.Pair;
import net.minecraft.world.World;

import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Predicate;

public class KeepInventoryPower extends Power {

    private final Predicate<Pair<World, ItemStack>> keepItemCondition;
    private final Set<Integer> slots;

    private ItemStack[] savedStacks;

    public KeepInventoryPower(PowerType<?> type, LivingEntity entity, Predicate<Pair<World, ItemStack>> keepItemCondition, Collection<Integer> slots) {
        super(type, entity);
        this.keepItemCondition = keepItemCondition;
        if(slots == null) {
            this.slots = null;
        } else {
            this.slots = new HashSet<>(slots);
        }
    }

    public void preventItemsFromDropping(Inventory inventory) {
        savedStacks = new ItemStack[inventory.size()];
        for(int i = 0; i < inventory.size(); i++) {
            if(slots != null && !slots.contains(i)) {
                continue;
            }
            ItemStack stack = inventory.getStack(i);
            if(!stack.isEmpty()) {
                if(keepItemCondition == null || keepItemCondition.test(new Pair<>(entity.getWorld(), stack))) {
                    savedStacks[i] = stack;
                    inventory.setStack(i, ItemStack.EMPTY);
                }
            }
        }
    }

    public void restoreSavedItems(Inventory inventory) {
        if(savedStacks == null) {
            Apoli.LOGGER.error(KeepInventoryPower.class.getSimpleName() +
                ": Tried to restore items without having saved any on entity \""
                + entity.getName().getString() + "\". Power may not have functioned correctly.");
            return;
        }
        if(inventory.size() != savedStacks.length) {
            Apoli.LOGGER.error(KeepInventoryPower.class.getSimpleName() +
                ": Tried to restore items with differently sized inventory on entity \""
                + entity.getName().getString() + "\". Items may have been lost.");
        }
        for(int i = 0; i < inventory.size() && i < savedStacks.length; i++) {
            if(savedStacks[i] != null && !savedStacks[i].isEmpty()) {
                inventory.setStack(i, savedStacks[i]);
            }
        }
        savedStacks = null;
    }

    public static PowerFactory createFactory() {
        return new PowerFactory<>(Apoli.identifier("keep_inventory"),
            new SerializableData()
                .add("item_condition", ApoliDataTypes.ITEM_CONDITION, null)
                .add("slots", SerializableDataTypes.INTS, null),
            data ->
                (type, player) -> new KeepInventoryPower(type, player, data.get("item_condition"), data.get("slots")))
            .allowCondition();
    }
}

package io.github.apace100.apoli.power;

import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.power.factory.PowerFactory;
import io.github.apace100.calio.data.SerializableData;
import io.github.ladysnake.pal.AbilitySource;
import io.github.ladysnake.pal.Pal;
import io.github.ladysnake.pal.PlayerAbility;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.util.Identifier;

public class PlayerAbilityPower extends Power {

    private final PlayerAbility ability;
    private final AbilitySource source;

    private boolean shouldRefresh;

    public PlayerAbilityPower(PowerType<?> type, LivingEntity entity, PlayerAbility playerAbility) {
        super(type, entity);
        this.ability = playerAbility;
        this.source = Pal.getAbilitySource(type.getIdentifier());
        if (entity instanceof PlayerEntity) {
            this.setTicking(true);
        }
    }

    @Override
    public NbtElement toTag() {

        NbtCompound rootNbt = new NbtCompound();
        rootNbt.putBoolean("ShouldRefresh", shouldRefresh);

        return rootNbt;

    }

    @Override
    public void fromTag(NbtElement tag) {
        if (tag instanceof NbtCompound rootNbt) {
            this.shouldRefresh = rootNbt.getBoolean("ShouldRefresh");
        }
    }

    @Override
    public void tick() {

        if (entity.getWorld().isClient || !(entity instanceof PlayerEntity playerEntity)) {
            return;
        }

        if (shouldRefresh) {

            ability.getTracker(playerEntity).refresh(true);
            shouldRefresh = false;

            return;

        }

        boolean active = this.isActive();
        boolean hasAbility = this.hasAbility();

        if (active && !hasAbility) {
            grantAbility();
        } else if (!active && hasAbility) {
            revokeAbility();
        }

    }

    @Override
    public void onAdded() {
        if (!entity.getWorld().isClient && entity instanceof PlayerEntity player && Apoli.LEGACY_POWER_SOURCE.grants(player, ability)) {
            Apoli.LEGACY_POWER_SOURCE.revokeFrom(player, ability);
        }
    }

    @Override
    public void onRemoved() {
        //  Indicate that the ability should be refreshed upon the entity being removed from a world
        this.shouldRefresh = true;
    }

    @Override
    public void onGained() {
        if (!entity.getWorld().isClient && this.isActive()) {
            grantAbility();
        }
    }

    @Override
    public void onLost() {
        if (!entity.getWorld().isClient) {
            revokeAbility();
        }
    }

    public boolean hasAbility() {
        return entity instanceof PlayerEntity playerEntity && source.grants(playerEntity, ability);
    }

    public void grantAbility() {
        if (entity instanceof PlayerEntity playerEntity) {
            source.grantTo(playerEntity, ability);
        }
    }

    public void revokeAbility() {
        if (entity instanceof PlayerEntity playerEntity) {
            source.revokeFrom(playerEntity, ability);
        }
    }

    public static PowerFactory createAbilityFactory(Identifier identifier, PlayerAbility ability) {
        return new PowerFactory<>(
            identifier,
            new SerializableData(),
